sys_script_client.script:
// Client Script: Type = onChange
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === oldValue) {
        return; // Exit if the form is loading or the value hasn't changed
    }

    // Define the mapping between State and Assignment Group
    var schemaToAssignmentGroupMap = {
        'FD': 'eb3120041bee6a542ac120a8b04bcb24', // sys_id  of the Assignment Group
        'HB': 'ac6164041bee6a542ac120a8b04bcb74', // sys_id  of the Assignment Group
        'HS': '9e61acc01bee6a542ac120a8b04bcbef', // sys_id  of the Assignment Group
		'HT': '7871a4041bee6a542ac120a8b04bcba4'  //sys_id  of the Assignment Group
    };

    // Get the Assignment Group value based on the selected State
    var assignmentGroupValue = schemaToAssignmentGroupMap[newValue];

    if (assignmentGroupValue) {
        // Set the Assignment Group field
        g_form.setValue('assignment_group', assignmentGroupValue); // Replace 'assignment_group' with the actual field name
    } else {
        // Clear the Assignment Group field if no mapping exists
        g_form.clearValue('assignment_group');
    }
}
